import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {resolve,dirname,relative} from 'node:path';
import {pathToFileURL} from 'node:url';
import {tmpdir} from 'node:os';
import ts from 'typescript';
const root=resolve('.');const out=resolve(tmpdir(),`countdown-tests-${process.pid}-${process.env.TEST_GEOCODER_URL?'configured':'off'}`);const seen=new Map();
export async function loadTS(path){const input=resolve(root,path);const key=input+(process.env.TEST_GEOCODER_URL??'');if(seen.has(key))return seen.get(key);const target=resolve(out,process.env.TEST_GEOCODER_URL?'configured':'off',relative(root,input)).replace(/\.ts$/,'.mjs');seen.set(key,target);await mkdir(dirname(target),{recursive:true});let source=await readFile(input,'utf8');const imports=[...source.matchAll(/from\s+['"](\.\.?\/[^'"]+)['"]/g)];for(const match of imports){const file=resolve(dirname(input),match[1]+(match[1].endsWith('.ts')?'':'.ts'));await loadTS(relative(root,file));source=source.replaceAll(`'${match[1]}'`,`'${match[1].replace(/\.ts$/,'')}.mjs'`).replaceAll(`"${match[1]}"`,`"${match[1].replace(/\.ts$/,'')}.mjs"`);}source=source.replace(/from\s+['"]([^.'"][^'"]*)['"]/g,(_,specifier)=>`from '${import.meta.resolve(specifier)}'`);source=source.replaceAll('import.meta.env.BASE_URL',JSON.stringify(process.env.BASE_PATH??'/')).replaceAll('import.meta.env.PUBLIC_SITE_ORIGIN',JSON.stringify('https://contagem.vivace-softwares.com.br')).replaceAll('import.meta.env.PUBLIC_MAP_TILES',JSON.stringify('https://tile.openstreetmap.org/{z}/{x}/{y}.png')).replaceAll('import.meta.env.PUBLIC_GEOCODER_URL',JSON.stringify(process.env.TEST_GEOCODER_URL??'')).replaceAll('import.meta.env.DEV','false').replaceAll('import.meta.env.PUBLIC_AD_TEST_MODE',"''");const {outputText}=ts.transpileModule(source,{compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.ESNext}});await writeFile(target,outputText);return target;}
export async function moduleTS(path){return import(pathToFileURL(await loadTS(path)).href);}
